CREATE TABLE IF NOT EXISTS governed_assets(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,asset_ref TEXT NOT NULL,asset_type TEXT NOT NULL,location_classification TEXT NOT NULL,rights_version TEXT NOT NULL,available_hours NUMERIC NOT NULL,used_hours NUMERIC NOT NULL,annual_cost NUMERIC(14,2) NOT NULL,valuation JSONB NOT NULL DEFAULT '{}'::jsonb,opportunity_type TEXT,constraints JSONB NOT NULL DEFAULT '[]'::jsonb,status TEXT NOT NULL DEFAULT 'inventoried',execution_reference TEXT,outcome JSONB,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,provenance JSONB NOT NULL,created_by BIGINT NOT NULL,approved_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,asset_ref),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('inventoried','baselined','candidate','review','approved','executed','measured','closed')),CHECK(available_hours>0 AND used_hours>=0 AND used_hours<=available_hours AND annual_cost>=0));
CREATE TABLE IF NOT EXISTS asset_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','manual_review')));
CREATE TABLE IF NOT EXISTS asset_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS asset_scope_idx ON governed_assets(tenant_id,status,asset_type);
